// Resumo curto do imóvel para o parâmetro {{2}} do template da Meta.
//
// NÃO HÁ coluna de resumo na `imoveis` — procurada nas 64 colunas. Usa-se o
// `titulo`, que é o que a agência escreveu para identificar o imóvel, e só
// quando ele falta se compõe um a partir dos campos estruturados.
//
// A `descricao` não serve de rede: 1100-1300 caracteres com quebras de linha a
// sério, e a Meta REJEITA parâmetros com quebras de linha — rejeita, não corta.

// Máximo observado nos 54 publicados: 101. Não é o limite da Meta (sobram 849
// para este parâmetro) — é o ponto a partir do qual o título deixa de
// identificar e passa a ser parágrafo. Aí vale mais a rede, que é sempre curta.
const MAX_TITULO = 120;

const n = (v) => (v === 0 || v ? v : null);
// A Meta recusa parâmetros com quebras de linha, tabs ou mais de 4 espaços
// seguidos. Achatar não é cosmético: é o que faz o pedido passar.
const achatar = (t) => String(t || '').replace(/\s+/g, ' ').trim();

// ── a rede: campos estruturados, preenchidos em 54/54 ──────────────────
// Tipologia. 17 dos 54 não têm `quartos`, e é correcto: 12 terrenos, 1 lote, 1
// armazém e 2 prédios de investimento. Zero apartamentos ou moradias, portanto
// omitir o T não esconde nada.
const tipo = [$json.natureza, n($json.quartos) ? 'T' + $json.quartos : null]
  .filter(Boolean).join(' ');

// `area_util` está a zero em 26; `area_bruta` recupera 15; os 11 que sobram são
// terrenos, e aí a área que conta é a do terreno.
const area = n($json.area_util) || n($json.area_bruta) || n($json.area_terreno);

// "São Julião da Figueira da Foz" é o nome oficial, mas a frase anterior já
// disse Figueira da Foz. As outras oito freguesias não têm sufixo.
const zona = String($json.freguesia || '').replace(/\s+d[ae]\s+Figueira da Foz$/i, '').trim();

const preco = n($json.venda_preco) || n($json.arrendamento_preco);
const euros = preco ? String(preco).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' \u20ac' : null;

const composto = [tipo, area ? area + ' m\u00b2' : null, zona, euros].filter(Boolean).join(', ');

// O título ganha: diz "T3+1 duplex com jardim privativo e vistas de mar", coisa
// que nenhum campo estruturado sabe. O FH2298 não tem nenhum — é o caso para
// que a rede existe.
const titulo = achatar($json.titulo);
const resumo = titulo && titulo.length <= MAX_TITULO ? titulo : composto;

return { json: { resumo } };
